// Modify ipv6_exthdrs_len to include bounds checking
static int ipv6_exthdrs_len(struct ipv6hdr *iph, const struct net_offload **opps) {
    struct ipv6_opt_hdr *opth = (void *)iph;
    int len = 0, proto, optlen = sizeof(*iph);

    proto = iph->nexthdr;
    for (;;) {
        if (proto != NEXTHDR_HOP) {
            *opps = rcu_dereference(inet6_offloads[proto]);
            if (unlikely(!(*opps)))
                break;

            if (!((*opps)->flags & INET6_PROTO_GSO_EXTHDR))
                break;
        }

        opth = (void *)opth + optlen;

        // Check for bounds violation
        if ((unsigned long)opth < (unsigned long)skb->data ||
            (unsigned long)opth > (unsigned long)skb_tail_pointer(skb)) {
            pr_err("ipv6_exthdrs_len: Bounds violation detected\n");
            break;
        }

        optlen = ipv6_optlen(opth);
        len += optlen;
        proto = opth->nexthdr;
    }
    return len;
}
